import{z as o,x as s,o as B,c as D,q as t,j as l,D as a,d as A,s as n,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"复现工作流收束","description":"","frontmatter":{"title":"复现工作流收束","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rw-map.md","filePath":"llm/rw-map.md","lastUpdated":1791413859000}'),p={name:"llm/rw-map.md"};function d(m,E,F,u,h,c){const r=s("Mermaid");return B(),D("div",null,[E[2]||(E[2]=t('<h1 id="复现工作流收束" tabindex="-1">复现工作流收束 <a class="header-anchor" href="#复现工作流收束" aria-label="Permalink to &quot;复现工作流收束&quot;">​</a></h1><div class="epigraph"><p>有组织的怀疑：共同体的每个主张都摆上检验台，不因出处显赫而免检。</p><footer>—— 据 Merton, The Normative Structure of Science, 1942 整理</footer></div><p><a href="/llm/rw-case-training-recipe">上一课</a>的配方案例走完，方法、实践、产出三个单元的课都已在手：判读与走读给了对照面，配置与预算给了跑道，归因与对齐给了判定，回馈与报告给了出口，两个案例验证了全流程在两类论文上的形态。本课收束：把十二课收成一张可执行的决策单、几条不变量、几件高频拦错事。本课程到此收束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>收束的缺口不是新知识，而是次序：十二课的方法若不成单，下次复现仍会从乱枪排查开始——先调学习率再查评测脚本，先押全量再想预算。训练基础设施的收束课立过一个口径：对账从后往前指，每一步的异常都能指回前一步的欠账。复现工作流需要同样的收法：一张按依赖排序的决策单，让「欠账」在花大钱之前就暴露。</p><p><span class="marginnote">「对账从后往前指」就像食品溯源码：货架上的每盒鸡蛋都能查到哪个养殖场、哪批饲料。报告结论是货架，run 是批次号，配置哈希是养殖场——链条任何一环查不到，这盒蛋就不能上架，结论同理降档。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>决策单九步，按依赖排。一，声明：类型、目标线、容差、范围、约束，一页纸。二，判读：报告抽出六行决策表，标披露档位。三，走读：仓库冻结到论文 tag，定位一步的产出物。四，账目：单一配置入口、哈希贯穿三处、种子分立。五，消融：从目标线倒推，同预算对照，过噪声带再判。六，归因：评测、数据、配置、初值、动态、全量，六步次序不许跳。七，预算：四级阶梯加闸门，归因消融占三到四成。八，对齐：四层锚点先粗后细，基线先校准再比高下。九，出口：回馈分级送上游，报告六节落档。</p><p>四条不变量。每个数字带坐标系；每个 run 可由四元组重建（配置哈希、代码、数据指纹、种子）；每个结论分档（强、中、弱、无）；每条死路可检索。对账从后往前指：报告里的结论点回 run，run 点回配置哈希，哈希点回代码 tag 与数据指纹——链条任一环断裂，结论降档，这就是九步互相咬合的意义。</p><p><span class="marginnote">数字实例：四条不变量落到一次汇报上就是四句话——「3 倍是 A100、每秒 8 请求负载下的 3 倍」「run 编号 9f3a 开头的那个哈希」「结论：中档，单种子」「tiny 级发散这条死路见台账第 41 条」。少任何一句，听众就得自己回去猜。</span></p>',10)),(B(),l(i,null,{default:a(()=>[n(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20D1%5B%221%20%E5%A3%B0%E6%98%8E%22%5D%20--%3E%20D2%5B%222%20%E5%88%A4%E8%AF%BB%22%5D%0A%20%20D2%20--%3E%20D3%5B%223%20%E8%B5%B0%E8%AF%BB%22%5D%0A%20%20D3%20--%3E%20D4%5B%224%20%E8%B4%A6%E7%9B%AE%22%5D%0A%20%20D4%20--%3E%20D5%5B%225%20%E6%B6%88%E8%9E%8D%22%5D%0A%20%20D5%20--%3E%20D6%5B%226%20%E5%BD%92%E5%9B%A0%22%5D%0A%20%20D6%20--%3E%20D7%5B%227%20%E9%A2%84%E7%AE%97%E9%98%B6%E6%A2%AF%22%5D%0A%20%20D7%20--%3E%20D8%5B%228%20%E5%AF%B9%E9%BD%90%E4%B8%8E%E6%A0%A1%E5%87%86%22%5D%0A%20%20D8%20--%3E%20D9%5B%229%20%E5%9B%9E%E9%A6%88%E4%B8%8E%E6%8A%A5%E5%91%8A%22%5D%0A%20%20D9%20--%3E%20LEDGER%5B%22%E5%AF%B9%E8%B4%A6%E4%BB%8E%E5%90%8E%E5%BE%80%E5%89%8D%E6%8C%87%EF%BC%9A%E7%BB%93%E8%AE%BA%E2%86%92run%E2%86%92%E5%93%88%E5%B8%8C%E2%86%92tag%E2%86%92%E6%8C%87%E7%BA%B9%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[A("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,"为什么不变量是这四条：它们分别封住四类事故。数字不带坐标，比较失义——判读课与案例课都撞见过的「3 倍」与「0.3 分」；run 不可重建，证据链断——账目课的哈希三处同一就是为它立的；结论不分档，弱结论搭车被引用——报告课的分档纪律；死路不可检索，团队重复付费——归档课的老规矩。四条都是「可检验性」在工程层的展开：Merton 的有组织怀疑落到团队里，就是让每个主张都带着自己的检验路径存在。",-1)),(B(),l(i,null,{default:a(()=>[n(r,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20INV1%5B%22%E4%B8%8D%E5%8F%98%E9%87%8F%EF%BC%9A%E6%95%B0%E5%AD%97%E5%B8%A6%E5%9D%90%E6%A0%87%E7%B3%BB%22%5D%20--%3E%20X1%5B%22%E5%B0%81%E4%BD%8F%EF%BC%9A%E8%B7%A8%E5%9D%90%E6%A0%87%E4%B9%B1%E6%AF%94%EF%BC%8C%E6%AF%94%E8%BE%83%E5%A4%B1%E4%B9%89%22%5D%0A%20%20INV2%5B%22%E4%B8%8D%E5%8F%98%E9%87%8F%EF%BC%9Arun%20%E5%9B%9B%E5%85%83%E7%BB%84%E5%8F%AF%E9%87%8D%E5%BB%BA%22%5D%20--%3E%20X2%5B%22%E5%B0%81%E4%BD%8F%EF%BC%9A%E8%AF%81%E6%8D%AE%E9%93%BE%E6%96%AD%E8%A3%82%22%5D%0A%20%20INV3%5B%22%E4%B8%8D%E5%8F%98%E9%87%8F%EF%BC%9A%E7%BB%93%E8%AE%BA%E5%88%86%E5%BC%BA%E4%B8%AD%E5%BC%B1%E6%97%A0%22%5D%20--%3E%20X3%5B%22%E5%B0%81%E4%BD%8F%EF%BC%9A%E5%BC%B1%E7%BB%93%E8%AE%BA%E6%90%AD%E8%BD%A6%E8%A2%AB%E5%BC%95%E7%94%A8%22%5D%0A%20%20INV4%5B%22%E4%B8%8D%E5%8F%98%E9%87%8F%EF%BC%9A%E6%AD%BB%E8%B7%AF%E5%8F%AF%E6%A3%80%E7%B4%A2%22%5D%20--%3E%20X4%5B%22%E5%B0%81%E4%BD%8F%EF%BC%9A%E5%9B%A2%E9%98%9F%E9%87%8D%E5%A4%8D%E4%BB%98%E8%B4%B9%22%5D%0A%20%20X1%20--%3E%20Y%5B%22%E5%8F%AF%E6%A3%80%E9%AA%8C%E6%80%A7%EF%BC%9A%E6%AF%8F%E4%B8%AA%E4%B8%BB%E5%BC%A0%E8%87%AA%E5%B8%A6%E6%A3%80%E9%AA%8C%E8%B7%AF%E5%BE%84%22%5D%0A%20%20X2%20--%3E%20Y%0A%20%20X3%20--%3E%20Y%0A%20%20X4%20--%3E%20Y%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=t('<p><span class="marginnote">常见误区：把三件高频拦错事当成「新手才会犯」。定目标线、调平基线、留归因预算，省下的都是现在的时间，代价延期到以后——资深团队犯的频率并不低，区别只在他们开工前有这张清单。</span></p><p>三件高频拦错事，按代价排：没定目标线就开工（全部后续判据悬空）、基线没调平就比高下（结论作废且难察觉）、全量押注不留归因预算（一次失败即归零）。三件事的共同点是事前一分钱的检查，事后十倍的账。</p><p><span class="marginnote">预算的实践起点：两个案例里，tiny 加 small 加 pilot 约占总算力的三到四成，却解决了绝大多数归因问题——比例不是定理，是防全押的结构件；领域方差越大（如强化学习），这个占比越高。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>收束不等于封闭。新论文形态会给坐标系加维度：长程 agent 实验把负载与轨迹长度带进坐标，多模态训练把模态配比带进决策表——九步的骨架不变，行的内容会换。复现的许可与伦理边界随配方公开程度收紧或放松，回馈时按上游条款走。还有一条常被漏掉的出口：「不复现」也是合法决定——成本超过决策价值时，把它写成显式声明（读了什么、估了什么、为什么停），进同一套台账；沉默的不复现只会让下一个排队的人重新估一遍价。到此，复现工作流收束：类型定靶，判读与走读出对照，账目出跑道，消融与归因出判定，预算出闸门，对齐出验收，回馈与报告出口——本课程到此收束。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>决策单九步按依赖排：声明、判读、走读、账目、消融、归因、预算、对齐、出口。</li><li>四条不变量：数字带坐标、run 可重建、结论分档、死路可检索；对账从后往前指。</li><li>三件高频拦错事：没定目标线、基线没调平、全量押注——事前便宜，事后昂贵。</li><li>「不复现」写成显式决定进台账；新论文形态换决策表的行，不换骨架。</li><li>出处：Merton, 1942；账目与配方口径见<a href="/llm/ti-map">训练基础设施收束</a>；按本课程十二课整理。</li></ul>',7))])}const _=o(p,[["render",d]]);export{f as __pageData,_ as default};
